// Semantic icon aliases — keep canonical SVG bodies centralized.
icons.gear = icons.settings;
icons.share = '<g fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m8.7 13.5 6.6 4m0-11-6.6 4"/></g>';
icons['nav-dashboards'] = '<g fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18"/><path d="M9 9v12"/><path d="M15 9v5"/></g>';
const iconViewBoxes = {
  "editing-design": "0 0 1200 1175",
  "console-game": "0 0 1200 937",
  "withicons-skeuo-images": "0 0 24 24",
  'premium-app': "0 0 1092 1200",
  'withicons-lunar:crown': '0 0 24 24',
  'streamline-plump-color:star-medal': '0 0 48 48',
  'trophy-v1': '0 0 128 128',
  'video-game': '0 0 128 128'
};
let crownGradientSequence = 0;
let trophyV1Sequence = 0;

function icon(name, cls='icon', label='') {
  let body = icons[name] || icons.info;

  if (name === 'withicons-lunar:crown') {
    const gradientId = `jyyr-crown-gradient-${++crownGradientSequence}`;
    body = body.replace(/SVGjjqMcdLQ/g, gradientId);
  }

  if (name === 'trophy-v1') {
    const svgId = `jyyr-trophy-v1-${++trophyV1Sequence}`;
    body = body.replace(/SVGKFFKCdLp/g, svgId);
  }

  const viewBox = iconViewBoxes[name] || (
    name === 'qris' ? '0 0 108.37466 17.412731' : '0 0 24 24'
  );
  const stroke = iconViewBoxes[name] ? 'none' : 'currentColor';
  const aria = label ? ` role="img" aria-label="${String(label).replace(/"/g,'&quot;')}"` : ' aria-hidden="true"';

  return `<svg class="${cls}" viewBox="${viewBox}" fill="none" stroke="${stroke}" stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round"${aria}>${body}</svg>`;
}
module.exports = { icon, icons };
